unsigned flac_process_audio_data(SF_PRIVATE *psf, unsigned len) {
    unsigned bytes_read = 0;
    unsigned remaining = len;
    unsigned char *buffer = psf->buffer;

    if (psf->frame_remaining > 0) {
        unsigned copy = (psf->frame_remaining < len) ? psf->frame_remaining : len;
        memcpy(buffer, psf->frame_buffer + psf->frame_position, copy);
        psf->frame_position += copy;
        psf->frame_remaining -= copy;
        buffer += copy;
        bytes_read += copy;
        remaining -= copy;

        if (remaining == 0)
            return bytes_read;
    }

    while (remaining > 0) {
        unsigned decode_result = flac_decode_audio_frame(psf, buffer, remaining);
        if (decode_result == 0)
            break; // End of stream or error

        buffer += decode_result;
        bytes_read += decode_result;
        remaining -= decode_result;
    }

    return bytes_read;
}

unsigned flac_process_audio_loop(SF_PRIVATE *psf, unsigned len)
{
    unsigned total_read = 0;
    unsigned bytes_remaining = len;
    FLAC__uint64 position = psf->dataoffset + psf->current_frame;

    if (psf->frame_remaining > 0) {
        unsigned to_copy = (bytes_remaining < psf->frame_remaining) ? bytes_remaining : psf->frame_remaining;
        memcpy(psf->buffer + total_read, psf->frame_buffer, to_copy);
        total_read += to_copy;
        psf->frame_remaining -= to_copy;
        psf->frame_buffer += to_copy;
        bytes_remaining -= to_copy;
    }

    while (bytes_remaining > 0 && !psf->eof) {
        unsigned decoded = flac_decode_audio(psf, psf->buffer + total_read, bytes_remaining);
        if (decoded == 0)
            break;
        total_read += decoded;
        bytes_remaining -= decoded;
    }

    return total_read;
}

unsigned flac_decoder_audio_read(SF_PRIVATE *psf, unsigned len) {
    unsigned bytes_read = 0;
    unsigned remaining = len;
    unsigned position = 0;

    if (psf->frame_available > 0) {
        unsigned bytes_to_copy = psf->frame_available < remaining ? psf->frame_available : remaining;
        memcpy(psf->buffer + position, psf->frame_buffer, bytes_to_copy);
        position += bytes_to_copy;
        bytes_read += bytes_to_copy;
        psf->frame_available -= bytes_to_copy;
        remaining -= bytes_to_copy;
    }

    while (remaining > 0 && !psf->eof_reached) {
        if (!flac_decode_audio_frame(psf)) {
            break;
        }

        unsigned bytes_to_copy = psf->frame_available < remaining ? psf->frame_available : remaining;
        memcpy(psf->buffer + position, psf->frame_buffer, bytes_to_copy);
        position += bytes_to_copy;
        bytes_read += bytes_to_copy;
        psf->frame_available -= bytes_to_copy;
        remaining -= bytes_to_copy;
    }

    return bytes_read;
}

unsigned flac_process_audio_data(SF_PRIVATE *psf, unsigned len)
{
    unsigned bytes_read = 0;
    unsigned remaining = len;
    unsigned position = 0;

    if (psf == NULL || len == 0)
        return 0;

    // Check if there is a frame available and not fully processed
    if (psf->frame_available > 0) {
        unsigned to_copy = SF_MIN(psf->frame_available, remaining);
        memcpy(psf->buffer + position, psf->frame_buffer, to_copy);
        position += to_copy;
        bytes_read += to_copy;
        psf->frame_available -= to_copy;
        remaining -= to_copy;
    }

    // Loop to decode audio data until len is reached or end of stream
    while (remaining > 0 && !psf->eof_reached) {
        int decoded_bytes = flac_decode_audio(psf, psf->buffer + position, remaining);
        if (decoded_bytes <= 0) {
            if (decoded_bytes == 0) {
                psf->eof_reached = 1;
                break;
            }
            // Error in decoding, break out of the loop
            break;
        }

        position += decoded_bytes;
        bytes_read += decoded_bytes;
        remaining -= decoded_bytes;
    }

    return bytes_read;
}

unsigned process_flac_audio_data(SF_PRIVATE *psf, unsigned len)
{
    unsigned bytes_read = 0;
    unsigned remaining = len;
    char *buffer = psf->buffer;
    unsigned buffer_pos = 0;
    unsigned buffer_len = psf->buffer_len;

    /* If a frame is available and not fully processed, copy the buffered data */
    if (buffer_len > 0) {
        unsigned to_copy = (buffer_len < remaining) ? buffer_len : remaining;
        memcpy(psf->current_position, buffer + buffer_pos, to_copy);
        buffer_pos += to_copy;
        bytes_read += to_copy;
        remaining -= to_copy;
    }

    while (remaining > 0) {
        unsigned frame_size = 0;

        /* Decode the next audio frame */
        frame_size = decode_flac_audio_frame(psf);

        if (frame_size == 0) {
            /* End of stream or an error occurred */
            break;
        }

        unsigned to_read = (frame_size < remaining) ? frame_size : remaining;
        memcpy(psf->current_position + bytes_read, psf->frame_buffer, to_read);
        bytes_read += to_read;
        remaining -= to_read;
    }

    return bytes_read;
}
